$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-production-atomic-live-swap-v0.1.0/test_custom_app_production_atomic_live_swap.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-atomic-live-swap-mutation.ps1')

$script:AtomicMutationFaultMode='none'
function Invoke-CustomAppProductionAtomicLiveSwapMutationValidationHookV010 {
    param([Parameter(Mandatory=$true)][string]$Checkpoint,[Parameter(Mandatory=$true)]$Context)
    switch($script:AtomicMutationFaultMode){
        'throw-before-live-move' {if($Checkpoint -ceq 'before-live-move'){throw 'fixture-mutation-before-live-move'}}
        'throw-after-live-move' {if($Checkpoint -ceq 'after-live-move'){throw 'fixture-mutation-after-live-move'}}
        'throw-after-candidate-move' {if($Checkpoint -ceq 'after-candidate-move'){throw 'fixture-mutation-after-candidate-move'}}
        'runtime-drift-after-swap' {if($Checkpoint -ceq 'after-candidate-move'){[IO.File]::AppendAllText((Join-Path ([string]$Context.live_path) 'index.js'),"// mutation-runtime-drift`n",[Text.UTF8Encoding]::new($false))}}
        'git-drift-after-swap' {if($Checkpoint -ceq 'after-candidate-move'){[IO.File]::AppendAllText((Join-Path ([string]$Context.live_path) '.git\config'),"# mutation-git-drift`n",[Text.UTF8Encoding]::new($false))}}
        'persistence-drift-after-swap' {if($Checkpoint -ceq 'before-persistence-postcheck'){$cfg=Join-Path ([string]$Context.appdata) 'spicetify\config-xpui.ini';[IO.File]::AppendAllText($cfg,"# mutation-persistence-drift`n",[Text.UTF8Encoding]::new($false))}}
        'throw-after-post-verify' {if($Checkpoint -ceq 'after-post-verify'){throw 'fixture-mutation-after-post-verify'}}
    }
}

function Invoke-MutationFixtureV010 {
    param($Fixture,[string]$Fault='none',[string]$AdmissionFingerprint=$null,[DateTimeOffset]$At=$now.AddSeconds(4))
    if([string]::IsNullOrWhiteSpace($AdmissionFingerprint)){$AdmissionFingerprint=[string]$Fixture.prepared.result.pre_apply_admission_fingerprint}
    $script:AtomicMutationFaultMode=$Fault
    Invoke-CustomAppProductionAtomicLiveSwapMutationV010 -Name ([string]$Fixture.q.x.f.name) -CallerAdmissionManagedBy 'fixture-qualified-admission-v1' -CallerAdmissionFingerprint $AdmissionFingerprint -LivePath ([string]$Fixture.q.x.live) -StagePath ([string]$Fixture.prepared.result.stage_path) -ExpectedLiveRuntimeTreeSha256 ([string]$Fixture.runtime_before.tree_sha256) -ExpectedLiveFullTreeSha256 ([string]$Fixture.full_before.tree_sha256) -ExpectedLiveFullFileCount ([int]$Fixture.full_before.file_count) -ExpectedLiveFullTotalBytes ([int64]$Fixture.full_before.total_bytes) -ExpectedStageRuntimeTreeSha256 ([string]$Fixture.prepared.result.stage_tree_sha256) -AppBackupPath ([string]$Fixture.prepared.result.app_backup_path) -ExpectedAppBackupTreeSha256 ([string]$Fixture.prepared.result.app_backup_tree_sha256) -ExpectedAppBackupFileCount ([int]$Fixture.prepared.result.app_backup_file_count) -ExpectedAppBackupTotalBytes ([int64]$Fixture.prepared.result.app_backup_total_bytes) -PersistenceBackupPath ([string]$Fixture.prepared.result.persistence_backup_path) -ExpectedPersistenceFingerprint ([string]$Fixture.prepared.result.persistence_fingerprint) -LocalAppDataRoot ([string]$Fixture.q.persistence.local) -AppDataRoot ([string]$Fixture.q.persistence.roaming) -Now $At
}

function Get-MutationTransactionRootV010 {param($Result);if($null -eq $Result){return $null};if([bool]$Result.ok -and $null -ne $Result.result){return [string]$Result.result.transaction_root};if($Result.PSObject.Properties['transaction_root']){return [string]$Result.transaction_root};return $null}
function Restore-MutationFixtureV010 {
    param($Fixture,$Result,[string]$Label)
    if($null -ne $Result -and [bool]$Result.ok){$rb=Restore-CustomAppProductionAtomicLiveSwapV010 -LivePath ([string]$Fixture.q.x.live) -AppBackupPath ([string]$Fixture.prepared.result.app_backup_path) -ExpectedAppBackupTreeSha256 ([string]$Fixture.prepared.result.app_backup_tree_sha256) -PersistenceBackupPath ([string]$Fixture.prepared.result.persistence_backup_path) -ExpectedPersistenceFingerprint ([string]$Fixture.prepared.result.persistence_fingerprint) -LocalAppDataRoot ([string]$Fixture.q.persistence.local) -AppDataRoot ([string]$Fixture.q.persistence.roaming);Assert-True ([bool]$rb.ok) "$Label cleanup restore failed"}
    $txn=Get-MutationTransactionRootV010 $Result;if(-not [string]::IsNullOrWhiteSpace($txn) -and (Test-Path -LiteralPath $txn)){$parent=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$Fixture.q.x.live));Remove-CustomAppAtomicDirectoryV010 -Path $txn -ExpectedParent $parent -ExpectedName ([IO.Path]::GetFileName($txn))}
}
function Restore-MutationFixturePreDriftV010 {param($Fixture,[string]$Label);$rb=Restore-CustomAppProductionAtomicLiveSwapV010 -LivePath ([string]$Fixture.q.x.live) -AppBackupPath ([string]$Fixture.prepared.result.app_backup_path) -ExpectedAppBackupTreeSha256 ([string]$Fixture.prepared.result.app_backup_tree_sha256) -PersistenceBackupPath ([string]$Fixture.prepared.result.persistence_backup_path) -ExpectedPersistenceFingerprint ([string]$Fixture.prepared.result.persistence_fingerprint) -LocalAppDataRoot ([string]$Fixture.q.persistence.local) -AppDataRoot ([string]$Fixture.q.persistence.roaming);Assert-True ([bool]$rb.ok) "$Label cleanup restore failed"}

$mutationCount=0
$valid=New-AtomicFixtureV010 'mutation-valid';$r=Invoke-MutationFixtureV010 $valid
try{
    Assert-True ([bool]$r.ok) ('valid mutation primitive denied: '+[string]$r.reason);$check=Test-CustomAppProductionAtomicLiveSwapMutationResultV010 $r.result;Assert-True ([bool]$check.ok) ('valid mutation result invalid: '+[string]$check.reason)
    Assert-True ([string]$r.result.caller_admission_fingerprint -ceq [string]$valid.prepared.result.pre_apply_admission_fingerprint) 'caller admission evidence drifted';Assert-True ([string]$r.result.pre_live_runtime_tree_sha256 -ceq [string]$valid.runtime_before.tree_sha256) 'pre-live runtime evidence drifted';Assert-True ([string]$r.result.pre_live_full_tree_sha256 -ceq [string]$valid.full_before.tree_sha256) 'pre-live full tree evidence drifted';Assert-True ([string]$r.result.pre_stage_runtime_tree_sha256 -ceq [string]$valid.prepared.result.stage_tree_sha256) 'stage evidence drifted'
    $post=Get-CustomAppLocalRuntimeBaseline -Name $valid.q.x.f.name -AppPath $valid.q.x.live;Assert-True ([string]$post.tree_sha256 -ceq [string]$valid.prepared.result.stage_tree_sha256) 'valid mutation live not staged runtime';$git=Get-CustomAppUpdateTreeSnapshotV010 -Root (Join-Path $valid.q.x.live '.git');Assert-True ([string]$git.tree_sha256 -ceq [string]$valid.git_before.tree_sha256) 'valid mutation git drifted';$persist=Get-SpotifyPersistenceSnapshot -LocalAppDataRoot $valid.q.persistence.local -AppDataRoot $valid.q.persistence.roaming;Assert-True ([string]$persist.fingerprint -ceq [string]$valid.persistence_before.fingerprint) 'valid mutation persistence drifted';Assert-AtomicResultNoFutureAuthorityV010 $r.result 'valid mutation';$mutationCount++
}finally{Restore-MutationFixtureV010 $valid $r 'valid mutation'}

$future=New-AtomicFixtureV010 'mutation-future' -Name 'future-app' -Source 'owner/future-app' -Manifest 'Future App' -Nonce '12121212121212121212121212121212';$r=Invoke-MutationFixtureV010 $future
try{Assert-True ([bool]$r.ok) ('future mutation primitive denied: '+[string]$r.reason);Assert-AtomicResultNoFutureAuthorityV010 $r.result 'future mutation';$mutationCount++}finally{Restore-MutationFixtureV010 $future $r 'future mutation'}

$badAdmission=New-AtomicFixtureV010 'mutation-bad-admission' -Nonce '13131313131313131313131313131313';$r=Invoke-MutationFixtureV010 -Fixture $badAdmission -AdmissionFingerprint 'bad';Assert-AtomicPreMutationDeniedUnchangedV010 $badAdmission $r 'invalid caller admission fingerprint';Assert-True ([string]$r.reason -ceq 'atomic-mutation-sha-input-invalid') 'invalid caller admission reason drifted';$mutationCount++

$liveDrift=New-AtomicFixtureV010 'mutation-live-drift' -Nonce '14141414141414141414141414141414';[IO.File]::AppendAllText((Join-Path $liveDrift.q.x.live 'index.js'),"// mutation-pre-live-drift`n",[Text.UTF8Encoding]::new($false));$r=Invoke-MutationFixtureV010 $liveDrift;Assert-False ([bool]$r.ok) 'pre live runtime drift accepted';Assert-False ([bool]$r.mutation_started) 'pre live runtime drift mutated';Assert-True ([string]$r.reason -ceq 'atomic-mutation-live-runtime-mismatch') 'pre live runtime reason drifted';Restore-MutationFixturePreDriftV010 $liveDrift 'pre live runtime drift';$mutationCount++

$fullDrift=New-AtomicFixtureV010 'mutation-full-drift' -Nonce '15151515151515151515151515151515';$runtimeBeforeGit=Get-CustomAppLocalRuntimeBaseline -Name $fullDrift.q.x.f.name -AppPath $fullDrift.q.x.live;[IO.File]::AppendAllText((Join-Path $fullDrift.q.x.live '.git\config'),"# mutation-pre-git-only-drift`n",[Text.UTF8Encoding]::new($false));$runtimeAfterGit=Get-CustomAppLocalRuntimeBaseline -Name $fullDrift.q.x.f.name -AppPath $fullDrift.q.x.live;Assert-True ([string]$runtimeBeforeGit.tree_sha256 -ceq [string]$runtimeAfterGit.tree_sha256) 'git-only drift unexpectedly changed runtime baseline';$r=Invoke-MutationFixtureV010 $fullDrift;Assert-False ([bool]$r.ok) 'pre full-tree drift accepted';Assert-False ([bool]$r.mutation_started) 'pre full-tree drift mutated';Assert-True ([string]$r.reason -ceq 'atomic-mutation-live-full-tree-mismatch') 'pre full-tree reason drifted';Restore-MutationFixturePreDriftV010 $fullDrift 'pre full-tree drift';$mutationCount++

$stageDrift=New-AtomicFixtureV010 'mutation-stage-drift' -Nonce '16161616161616161616161616161616';[IO.File]::AppendAllText((Join-Path ([string]$stageDrift.prepared.result.stage_path) 'index.js'),"// mutation-pre-stage-drift`n",[Text.UTF8Encoding]::new($false));$r=Invoke-MutationFixtureV010 $stageDrift;Assert-False ([bool]$r.ok) 'pre stage drift accepted';Assert-False ([bool]$r.mutation_started) 'pre stage drift mutated';Assert-True ([string]$r.reason -ceq 'atomic-mutation-stage-runtime-mismatch') 'pre stage drift reason drifted';$mutationCount++

$backupDrift=New-AtomicFixtureV010 'mutation-backup-drift' -Nonce '17171717171717171717171717171717';[IO.File]::AppendAllText((Join-Path ([string]$backupDrift.prepared.result.app_backup_path) 'index.js'),"// mutation-backup-drift`n",[Text.UTF8Encoding]::new($false));$r=Invoke-MutationFixtureV010 $backupDrift;Assert-False ([bool]$r.ok) 'backup drift accepted';Assert-False ([bool]$r.mutation_started) 'backup drift mutated';Assert-True ([string]$r.reason -ceq 'atomic-mutation-app-backup-mismatch') 'backup drift reason changed';$mutationCount++

$persistDrift=New-AtomicFixtureV010 'mutation-persistence-drift' -Nonce '18181818181818181818181818181818';[IO.File]::AppendAllText((Join-Path $persistDrift.q.persistence.roaming 'spicetify\config-xpui.ini'),"# mutation-pre-persistence-drift`n",[Text.UTF8Encoding]::new($false));$r=Invoke-MutationFixtureV010 $persistDrift;Assert-False ([bool]$r.ok) 'pre persistence drift accepted';Assert-False ([bool]$r.mutation_started) 'pre persistence drift mutated';Assert-True ([string]$r.reason -ceq 'atomic-mutation-protected-persistence-drift-before-swap') 'pre persistence drift reason changed';Restore-MutationFixturePreDriftV010 $persistDrift 'pre persistence drift';$mutationCount++

$before=New-AtomicFixtureV010 'mutation-before' -Nonce '19191919191919191919191919191919';$r=Invoke-MutationFixtureV010 -Fixture $before -Fault 'throw-before-live-move';try{Assert-AtomicPreMutationDeniedUnchangedV010 $before $r 'mutation throw before live move';Assert-True ([string]$r.reason -like 'atomic-mutation-candidate-preparation-failed:*fixture-mutation-before-live-move*') 'mutation before-live reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $before $r 'mutation before-live'}

$afterMove=New-AtomicFixtureV010 'mutation-after-live' -Nonce '20202020202020202020202020202020';$r=Invoke-MutationFixtureV010 -Fixture $afterMove -Fault 'throw-after-live-move';try{Assert-AtomicPostMutationFailureRolledBackV010 $afterMove $r 'mutation throw after live move';Assert-True ([string]$r.reason -like '*fixture-mutation-after-live-move*') 'mutation after-live reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $afterMove $r 'mutation after-live'}

$afterCandidate=New-AtomicFixtureV010 'mutation-after-candidate' -Nonce '21212121212121212121212121212121';$r=Invoke-MutationFixtureV010 -Fixture $afterCandidate -Fault 'throw-after-candidate-move';try{Assert-AtomicPostMutationFailureRolledBackV010 $afterCandidate $r 'mutation throw after candidate move';Assert-True ([string]$r.reason -like '*fixture-mutation-after-candidate-move*') 'mutation after-candidate reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $afterCandidate $r 'mutation after-candidate'}

$runtimeFault=New-AtomicFixtureV010 'mutation-runtime-fault' -Nonce '22222222222222222222222222222222';$r=Invoke-MutationFixtureV010 -Fixture $runtimeFault -Fault 'runtime-drift-after-swap';try{Assert-AtomicPostMutationFailureRolledBackV010 $runtimeFault $r 'mutation runtime drift after swap';Assert-True ([string]$r.reason -like '*post-swap-runtime-mismatch*') 'mutation runtime fault reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $runtimeFault $r 'mutation runtime fault'}

$gitFault=New-AtomicFixtureV010 'mutation-git-fault' -Nonce '23232323232323232323232323232323';$r=Invoke-MutationFixtureV010 -Fixture $gitFault -Fault 'git-drift-after-swap';try{Assert-AtomicPostMutationFailureRolledBackV010 $gitFault $r 'mutation git drift after swap';Assert-True ([string]$r.reason -like '*post-swap-git-tree-mismatch*') 'mutation git fault reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $gitFault $r 'mutation git fault'}

$persistenceFault=New-AtomicFixtureV010 'mutation-persistence-fault' -Nonce '24242424242424242424242424242424';$r=Invoke-MutationFixtureV010 -Fixture $persistenceFault -Fault 'persistence-drift-after-swap';try{Assert-AtomicPostMutationFailureRolledBackV010 $persistenceFault $r 'mutation persistence drift after swap';Assert-True ([string]$r.reason -like '*protected-persistence-drift-after-swap*') 'mutation persistence fault reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $persistenceFault $r 'mutation persistence fault'}

$postVerify=New-AtomicFixtureV010 'mutation-post-verify' -Nonce '25252525252525252525252525252525';$r=Invoke-MutationFixtureV010 -Fixture $postVerify -Fault 'throw-after-post-verify';try{Assert-AtomicPostMutationFailureRolledBackV010 $postVerify $r 'mutation throw after post verify';Assert-True ([string]$r.reason -like '*fixture-mutation-after-post-verify*') 'mutation post-verify reason drifted';$mutationCount++}finally{Restore-MutationFixtureV010 $postVerify $r 'mutation post-verify'}

if($mutationCount -ne 15){throw "mutation matrix count mismatch $mutationCount != 15"}
Write-Host ('CUSTOM_APP_PRODUCTION_ATOMIC_LIVE_SWAP_MUTATION_MATRIX_PASS total='+$mutationCount)
